[Form]
public class GUPPriceMarginLedgerCopy extends FormRun
{
    GUPPriceMarginLedger priceMarginLedger;

}

public boolean validateProfileId()
{
    boolean ret = true;

    if (element.design().controlName(formControlStr(GUPPriceMarginLedgerCopy, PostingProfile)).valueStr() == '')
    {
        ret = checkFailed("@GlobalUnifiedPricing:GUPPostProfileCheck");
    }

    return ret;
}

public void init()
{
    super();

    if (element.args().record() is GUPPriceMarginLedger)
    {
        priceMarginLedger = element.args().record();
    }
}

public void copyPriceMarginLedger()
{
    ttsbegin;

    GUPPriceMarginLedger priceMarginLedgerTarget;

    priceMarginLedgerTarget.PostingProfile = PostingProfile.valueStr();
    priceMarginLedgerTarget.Description = Description.valueStr();
    priceMarginLedgerTarget.insert();

    RecId priceMarginLedgerRecId = priceMarginLedgerTarget.RecId;

    GUPPriceMarginLedgerAccounts priceMarginLedgerAccounts;
    GUPPriceMarginLedgerAccounts priceMarginLedgerAccountsTarget;
    insert_recordset priceMarginLedgerAccountsTarget (GUPPriceMarginLedger, AccountCode, AccountRelation, ItemCode, ItemRelation, ComponentAccount, OffsetAccount)
        select priceMarginLedgerRecId, AccountCode, AccountRelation, ItemCode, ItemRelation, ComponentAccount, OffsetAccount from priceMarginLedgerAccounts
            where priceMarginLedgerAccounts.GUPPriceMarginLedger == priceMarginLedger.RecId;

    ttscommit;
}

public void clicked()
{
    super();

    if (element.validateProfileId())
    {
        element.copyPriceMarginLedger();
        element.closeOk();
    }
}
